begin;
create extension if not exists pgtap;
select plan(25);
select has_column('qarar_meetings','meetings','quorum_percentage','quorum belongs to the meeting');
insert into public.organizations(id,code,name_ar) values('a9000000-0000-0000-0000-000000000001','s108','Quorum');
insert into auth.users(id,email) values('a9000000-0000-0000-0000-000000000011','admin@s108.test');
insert into public.users(id,organization_id,email,full_name_ar,is_system_admin) values('a9000000-0000-0000-0000-000000000011','a9000000-0000-0000-0000-000000000001','admin@s108.test','Admin',true);
insert into public.governance_unit_types(id,organization_id,code,name_ar) values('a9000000-0000-0000-0000-000000000021','a9000000-0000-0000-0000-000000000001','council','Council');
insert into public.governance_units(id,organization_id,unit_type_id,code,name_ar,status,quorum_percentage) values('a9000000-0000-0000-0000-000000000022','a9000000-0000-0000-0000-000000000001','a9000000-0000-0000-0000-000000000021','council','Council','active',80);
insert into public.meeting_types(id,organization_id,code,name_ar) values('a9000000-0000-0000-0000-000000000023','a9000000-0000-0000-0000-000000000001','normal','Normal');
create function pg_temp.s108_values() returns jsonb language sql as $$select jsonb_build_object('p_governance_unit_id','a9000000-0000-0000-0000-000000000022','p_meeting_type_id','a9000000-0000-0000-0000-000000000023','p_title_ar','Meeting quorum test','p_scheduled_date',current_date,'p_location_type','onsite','p_client_request_id','a9000000-0000-0000-0000-000000000041')$$;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000011","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),30)$$,'create with custom quorum');
reset role;
select is((select quorum_percentage from qarar_meetings.meetings where client_request_id='a9000000-0000-0000-0000-000000000041'),30,'custom quorum persisted');
select is((select quorum_percentage from public.governance_units where id='a9000000-0000-0000-0000-000000000022'),80,'council unchanged');
set local role authenticated;
select lives_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),30)$$,'same receipt replays');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),40)$$,'40001',null,'receipt cannot rewrite quorum');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),0)$$,'22023',null,'zero rejected');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),101)$$,'22023',null,'over 100 rejected');
select lives_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values()||'{"p_client_request_id":"a9000000-0000-0000-0000-000000000042"}',null)$$,'optional quorum');
reset role;
select is((select quorum_percentage from qarar_meetings.meetings where client_request_id='a9000000-0000-0000-0000-000000000042'),51,'default independent of council');
select is((select count(*)::integer from qarar_meetings.meetings where organization_id='a9000000-0000-0000-0000-000000000001'),2,'no duplicated or partial meetings');
select ok(exists(select 1 from qarar_audit.audit_logs where organization_id='a9000000-0000-0000-0000-000000000001' and action='meetings.quorum.set'),'quorum audited');
create function pg_temp.s108_edit() returns jsonb language sql security definer as $$select jsonb_build_object('p_meeting_id',id,'p_title_ar',title_ar,'p_scheduled_date',scheduled_date,'p_location_type',location_type,'p_meeting_type_id',meeting_type_id,'p_expected_updated_at',updated_at) from qarar_meetings.meetings where client_request_id='a9000000-0000-0000-0000-000000000041'$$;
set local role authenticated;
select lives_ok($$select api_v2.save_meeting_with_quorum_v2('update',pg_temp.s108_edit(),60)$$,'edit own draft atomically');
select is((api_v1.get_meeting_detail((pg_temp.s108_edit()->>'p_meeting_id')::uuid)->>'quorum_percentage')::integer,60,'details expose saved quorum');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('update',pg_temp.s108_edit()||'{"p_expected_updated_at":"2000-01-01T00:00:00Z"}',70)$$,'40001',null,'stale edit rejected');
select lives_ok($$select api_v2.save_meeting_with_quorum_v2('series',pg_temp.s108_values()||jsonb_build_object('p_first_date',current_date,'p_frequency','monthly','p_interval_count',1,'p_occurrence_count',2),40)$$,'series stores a quorum for each occurrence');
reset role;
select is((select count(*)::integer from qarar_meetings.meetings where organization_id='a9000000-0000-0000-0000-000000000001' and quorum_percentage=40),2,'both occurrences saved');
insert into auth.users(id,email) values('a9000000-0000-0000-0000-000000000012','reader@s108.test');
insert into public.users(id,organization_id,email,full_name_ar) values('a9000000-0000-0000-0000-000000000012','a9000000-0000-0000-0000-000000000001','reader@s108.test','Reader');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000012","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('update',pg_temp.s108_edit(),70)$$,'42501',null,'unprivileged update denied');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('create',pg_temp.s108_values(),30)$$,'42501',null,'unprivileged creation denied');
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('update',pg_temp.s108_edit()||'{"p_meeting_id":"a9000000-0000-0000-0000-000000000099"}',70)$$,'P0002',null,'unavailable resource denied');
reset role;
select set_config('session_replication_role','replica',true);
update qarar_meetings.meetings set status='in_progress' where client_request_id='a9000000-0000-0000-0000-000000000041';
select set_config('session_replication_role','origin',true);
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000011","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select api_v2.save_meeting_with_quorum_v2('update',pg_temp.s108_edit(),70)$$,'23514',null,'live quorum frozen even for admin');
reset role;
select is((select quorum_percentage from qarar_meetings.meetings where client_request_id='a9000000-0000-0000-0000-000000000042'),51,'other meeting still unchanged');
-- The same real roster is met at 30% but not at 51%, regardless of council 80%.
insert into auth.users(id,email) values('a9000000-0000-0000-0000-000000000013','member@s108.test');
insert into public.users(id,organization_id,email,full_name_ar) values('a9000000-0000-0000-0000-000000000013','a9000000-0000-0000-0000-000000000001','member@s108.test','Member');
insert into public.roles(id,organization_id,code,name_ar,role_scope) values('a9000000-0000-0000-0000-000000000031','a9000000-0000-0000-0000-000000000001','s108_member','Member','governance_unit');
insert into public.memberships(organization_id,user_id,governance_unit_id,role_id)
select organization_id,id,'a9000000-0000-0000-0000-000000000022','a9000000-0000-0000-0000-000000000031' from public.users where organization_id='a9000000-0000-0000-0000-000000000001';
insert into public.attendance_records(organization_id,meeting_id,user_id,membership_id,attendance_status)
select m.organization_id,mt.id,m.user_id,m.id,case when m.user_id='a9000000-0000-0000-0000-000000000011' then 'present' else 'absent' end
from public.memberships m cross join qarar_meetings.meetings mt
where m.organization_id='a9000000-0000-0000-0000-000000000001' and mt.organization_id=m.organization_id and mt.client_request_id in('a9000000-0000-0000-0000-000000000041','a9000000-0000-0000-0000-000000000042');
update qarar_meetings.meetings set quorum_percentage=30 where client_request_id='a9000000-0000-0000-0000-000000000041';
set local role authenticated;
select is(api_v1.recalculate_meeting_quorum((pg_temp.s108_edit()->>'p_meeting_id')::uuid,true)->>'quorum_status','met','meeting 30% meets actual one of three');
select is((api_v1.recalculate_meeting_quorum((pg_temp.s108_edit()->>'p_meeting_id')::uuid,true)->>'required_percentage')::integer,30,'snapshot uses meeting quorum');
reset role;
select is((select qarar_attendance.calculate_meeting_quorum(id) from qarar_meetings.meetings where client_request_id='a9000000-0000-0000-0000-000000000042'),'not_met','legacy calculation respects other meeting 51%');
select * from finish();
rollback;
